import {traits,band} from './model.mjs';
import {categoryInsight} from './report.mjs';
import {lifeStory,scorePosition,profileHighlights,responseEvidence} from './report-stories.mjs';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function overviewMarkup(report,language='en'){
 const hi=language==='hi',h=profileHighlights(report.scores),a=categoryInsight(report.scores,h.pronounced.index),b=categoryInsight(report.scores,h.mixed.index);
 return `<section class="report-panel personal-overview" data-no-translate><p class="eyebrow">${hi?'आपके जवाबों से आपकी कहानी':'YOUR ANSWERS, IN YOUR OWN LIFE'}</p><h2>${hi?'सिर्फ़ नंबर नहीं। समझने की एक शुरुआत।':'More than numbers. A starting point for understanding.'}</h2><p>${hi?'ये आपकी बताई हुई पसंद हैं। परिस्थितियाँ, ऊर्जा और अनुभव भी मायने रखते हैं। जो बात मेल खाए, उसे रखें; जो न मिले, उस पर सवाल करें।':'These are the preferences you described. Your situation, energy and experience matter too. Keep what resonates and question what does not.'}</p><div class="personal-highlights"><button data-category="${a.index}"><span>${hi?'सबसे स्पष्ट बताई पसंद':'Most pronounced preference'}</span><strong>${h.allMixed?(hi?'दोनों ओर की जगह':'Room for both sides'):esc(a.title)}</strong><small>${esc(a.trait.name)} · ${a.score} / 100</small><span>${hi?'इसका मतलब देखें →':'Explore what this means →'}</span></button><button data-category="${b.index}"><span>${hi?'मध्य बिंदु के सबसे पास':'Closest to the midpoint'}</span><strong>${esc(b.trait.name)}</strong><small>${b.score} / 100 · ${h.mixed.distance<=10?(hi?'दोनों ओर की पसंद दिख सकती है':'Both sides may show up'):(hi?'आपके पाँच scores में मध्य के सबसे पास':'Nearest to 50 among your five scores')}</small><span>${hi?'अपना संदर्भ देखें →':'Find your own context →'}</span></button></div><p class="personal-reassurance">${hi?'कोई आदर्श आकार या सबसे अच्छा score नहीं है। अलग पसंद एक साथ हो सकती हैं।':'There is no ideal shape or best score. Different preferences can belong to the same person.'}</p></section>`;
}
export function scoreLensMarkup(report,index,language='en'){
 const hi=language==='hi',item=categoryInsight(report.scores,index),position=scorePosition(item.score,language),low=esc(item.trait.low),high=esc(item.trait.high),lean=position.band===1?(hi?'मध्य हिस्से में':'in the middle range'):position.band===0?(hi?`${low} की ओर`:`toward ${low}`):(hi?`${high} की ओर`:`toward ${high}`);
 return `<div class="score-lens"><div class="score-lens-top"><span>${hi?'आपकी पसंद की स्थिति':'Your preference position'}</span><strong>${item.score}<small> / 100</small></strong></div><svg class="score-ruler" viewBox="0 0 400 76" role="img" aria-label="${hi?`${item.score} / 100, ${lean}`:`${item.score} out of 100, ${lean}`}"><rect x="18" y="20" width="364" height="12" rx="6" fill="#e8edf6"/><rect x="163.6" y="17" width="72.8" height="18" rx="6" fill="#cbd7f1"/><path d="M200 12v28" stroke="#8394b5" stroke-dasharray="3 3"/>${[0,25,50,75,100].map(n=>`<path d="M${18+n*3.64} 39v5" stroke="#a7b3c9"/><text x="${18+n*3.64}" y="63" text-anchor="middle" fill="#627087" font-size="14">${n}</text>`).join('')}<circle cx="${18+item.score*3.64}" cy="26" r="10" fill="${item.trait.color}" stroke="white" stroke-width="3"/></svg><div class="lens-endpoints"><span>${low}</span><span>${high}</span></div><p><strong>${position.label}.</strong> ${hi?`आपके जवाब ${lean} हैं। यह आपकी क्षमता या दूसरे लोगों से तुलना नहीं बताता।`:`Your answers sit ${lean}. This describes a preference, not your ability or a comparison with other people.`}</p></div>`;
}
export function personalDetailMarkup(report,index,{language='en',context='daily',added=false}={}){
 const hi=language==='hi',item=categoryInsight(report.scores,index),story=lifeStory(report.scores,index,language),contexts=hi?{daily:'रोज़मर्रा में',relationships:'रिश्तों में',pressure:'दबाव में'}:{daily:'Everyday life',relationships:'Relationships',pressure:'Under pressure'},active=contexts[context]?context:'daily',feedback=['fits','depends','different'].includes(report.reflections?.[index])?report.reflections[index]:null;
 return `<div data-no-translate><div class="category-detail-heading"><div><div class="eyebrow">${esc(item.trait.name)}</div><h3>${esc(item.title)}</h3></div></div>${scoreLensMarkup(report,index,language)}<p class="personal-meaning">${esc(item.meaning)}</p><div class="life-contexts" role="group" aria-label="${hi?'अपने जीवन का संदर्भ चुनें':'Choose a context in your life'}">${Object.entries(contexts).map(([key,label])=>`<button data-life-context="${key}" aria-pressed="${key===active}">${label}</button>`).join('')}</div><div class="life-story" role="status" aria-live="polite"><h4>${contexts[active]}</h4><p>${esc(story[active])}</p></div><div class="supporting-need"><h4>${hi?'आपके लिए क्या मददगार हो सकता है':'What may help you feel supported'}</h4><p>${esc(story.need)}</p></div><details class="personal-strength"><summary>${hi?'आपकी संभावित खूबियाँ और ध्यान रखने की बात':'A strength to use, and something to watch'}</summary><h4>${hi?'आपकी खूबी':'Your strength'}</h4><p>${esc(item.strength)}</p><h4>${hi?'किस बात पर ध्यान दें':'One thing to watch for'}</h4><p>${esc(item.watch)}</p></details><div class="category-suggestion"><h4>${hi?'एक छोटा कदम, आज के लिए':'One small step for today'}</h4><p>${esc(item.step)}</p><button class="${added?'secondary':'primary'}" id="add-category-action" ${added?'disabled':''}>${hi?(added?'योजना में जुड़ गया ✓':'मेरी योजना में जोड़ें +'):(added?'Added to your plan ✓':'Add to my plan +')}</button></div><div class="reflection-check"><h4>${hi?'क्या यह आपके अनुभव से मेल खाता है?':'Does this feel like you?'}</h4><div class="reflection-options">${(hi?[['fits','मुझसे मेल खाता है'],['depends','स्थिति पर निर्भर है'],['different','मेरे लिए अलग है']]:[['fits','Feels like me'],['depends','Depends on the situation'],['different','Not quite me']]).map(([key,label])=>`<button data-reflection="${key}" aria-pressed="${feedback===key}">${label}</button>`).join('')}</div><p id="reflection-status" role="status">${feedback?(hi?'आपकी बात इस browser में सेव है। Score नहीं बदला है। आपकी अपनी समझ भी इस रिपोर्ट का हिस्सा है।':'Your reflection is saved in this browser. Your score stays the same. Your own perspective belongs alongside the numbers.'):(hi?'आपका अनुभव मायने रखता है। यह प्रतिक्रिया score को नहीं बदलेगी।':'Your experience matters. This reflection will not change your score.')}</p></div><div class="print-life-stories">${Object.entries(contexts).map(([key,label])=>`<h4>${label}</h4><p>${esc(story[key])}</p>`).join('')}</div></div>`;
}
export function evidenceMarkup(report,index,{language='en',filter=null}={}){
 const hi=language==='hi',items=responseEvidence(report,index),name=esc(traits[index].name);
 if(items===null)return `<section class="report-panel evidence-panel" data-no-translate><h2>${hi?'इस score के पीछे के जवाब':'The answers behind this score'}</h2><p>${hi?'इस रिपोर्ट में केवल scores सेव हैं। अब से पूरे किए गए टेस्ट में अलग-अलग जवाबों का विवरण भी मिलेगा।':'This saved report contains scores only. Assessments completed from now on include answer-by-answer detail.'}</p></section>`;
 const counts=Array.from({length:5},(_,answer)=>items.filter(i=>i.answer===answer).length),labels=hi?['बिल्कुल असहमत','असहमत','न सहमत, न असहमत','सहमत','पूरी तरह सहमत']:['Strongly disagree','Disagree','Neither agree nor disagree','Agree','Strongly agree'],validFilter=Number.isInteger(filter)&&filter>=0&&filter<5?filter:null,shown=validFilter===null?items:items.filter(item=>item.answer===validFilter),sum=items.reduce((n,item)=>n+item.scored,0),score=report.scores[index];
 const rows=list=>list.map(item=>`<li><p><span class="evidence-question-number">${hi?'सवाल':'Question'} ${item.number}</span>${esc(item.text)}</p><strong>${esc(item.label)}</strong>${item.reverse?`<small>${hi?'इस सवाल के शब्दों के अनुसार scoring की दिशा उलटी है।':'This item is reverse-scored to account for its wording.'}</small>`:''}</li>`).join('');
 return `<section class="report-panel evidence-panel" data-no-translate><div class="evidence-heading"><div><p class="eyebrow">${name}</p><h2>${hi?'आपके जवाबों से बना यह score':'How your answers shaped this score'}</h2></div><span>${items.length} ${hi?'जवाब':'responses'}</span></div><p>${hi?'नीचे आपके चुने हुए जवाबों की गिनती है। किसी column को चुनकर उसी तरह के जवाब देखें। यह graph व्यक्तित्व के हिस्से या गुणवत्ता नहीं दिखाता।':'These columns count the responses you selected. Choose a column to explore those answers. This is a response pattern, not parts or quality of your personality.'}</p><div class="response-histogram" role="group" aria-label="${hi?'जवाब के अनुसार छाँटें':'Filter answers by response'}">${counts.map((count,i)=>`<button data-response-filter="${i}" aria-pressed="${validFilter===i}" ${count===0?'disabled':''} aria-label="${esc(labels[i])}, ${count} ${hi?'जवाब':'responses'}"><span class="histogram-column"><span style="height:${count/items.length*100}%;--response-color:${['#c17b81','#cfaa68','#a2a6bd','#8aaa9b','#729e92'][i]}"></span><strong>${count}</strong></span><span class="histogram-label">${labels[i]}</span></button>`).join('')}</div><button class="text-button" data-response-filter="all" aria-pressed="${validFilter===null}">${hi?'सभी जवाब देखें':'Show all responses'}</button><p class="evidence-filter-status" role="status">${hi?`${items.length} में से ${shown.length} जवाब दिख रहे हैं।`:`Showing ${shown.length} of ${items.length} responses.`}</p><details class="evidence-answers"><summary>${hi?'मेरे चुने हुए जवाब देखें':'See the answers I selected'}</summary><ol class="evidence-list">${rows(shown)}</ol><ol class="evidence-print-all">${rows(items)}</ol></details><details class="evidence-calculation"><summary>${hi?'यह नंबर कैसे निकला?':'How did these answers become this number?'}</summary><p>${hi?'हर जवाब को 0–4 में score किया जाता है। उलटी दिशा वाले सवालों को उसी अनुसार समायोजित किया जाता है। इस आयाम के सभी जवाब गिनती में शामिल हैं, चाहे ऊपर की सूची छाँटी गई हो।':'Responses are scored from 0–4. Reverse-worded items are adjusted before adding them together. Every response in this dimension is included, even when the list above is filtered.'}</p><p class="score-equation"><bdi dir="ltr">${sum} ÷ ${items.length*4} × 100 ≈ ${score}</bdi></p><p>${hi?'यह निकटतम पूर्ण संख्या तक round किया गया preference score है, प्रतिशत लोगों से तुलना नहीं।':'This is your preference score rounded to the nearest whole number, not a population percentile.'}</p></details></section>`;
}
export function chartReadingMarkup(key,report,index,series=[],language='en'){
 const hi=language==='hi',item=categoryInsight(report.scores,index),name=esc(item.trait.name),score=item.score,position=scorePosition(score,language),endpoint=esc(position.band===0?item.trait.low:position.band===2?item.trait.high:item.title);let title,text;
 if(key==='line'){title=hi?'समय के साथ आपकी अपनी झलक':'Your own snapshots over time';const first=series[0],last=series.at(-1);text=series.length<2?(hi?'यह आपकी पहली saved झलक है। जब चाहें, एक और assessment पूरा करके समय के साथ अपने जवाबों की तुलना करें।':'Your first snapshot is here. Complete another assessment whenever you want to compare your own responses over time.'):(hi?`${name}: पहले ${first.score}, सबसे हाल में ${last.score}। ${Math.abs(last.score-first.score)} points का अंतर है। परिस्थिति या जवाब देने का तरीका बदल सकता है; यह अपने आप सुधार या गिरावट नहीं है।`:`${name}: ${first.score} in the earliest shown assessment, ${last.score} in the latest. That is ${Math.abs(last.score-first.score)} points apart. Context and responses can change; this does not automatically mean improvement or decline.`)}
 else if(key==='pie'){title=hi?'पाँच पसंदों की grouping':'How your five preferences group together';const counts=[0,0,0];report.scores.forEach(s=>counts[band(s)]++);text=hi?`${counts[0]} dimensions बाईं ओर, ${counts[1]} मध्य में और ${counts[2]} दाईं ओर हैं। हर slice dimensions की गिनती है। किसी slice को चुनकर उसके dimensions देखें।`:`${counts[0]} dimensions lean toward their left endpoint, ${counts[1]} sit in the middle, and ${counts[2]} lean toward their right endpoint. Each slice counts dimensions. Select one to see which preferences it contains.`}
 else{title=hi?`${name}: ${score} को कैसे पढ़ें`:`${name}: how to read ${score}`;text=hi?`${score} / 100 ${position.band===1?'इस scale के मध्य हिस्से में है':`${endpoint} की ओर झुकाव दिखाता है`}। दोनों ओर की पसंद की अपनी जगह है। ${key==='map'?'किसी point को चुनकर उसकी कहानी खोलें।':'किसी bar को चुनकर उसका अर्थ और सुझाव देखें।'}`:`${score} / 100 ${position.band===1?`sits in the middle range between “${esc(item.trait.low)}” and “${esc(item.trait.high)}”`:`leans toward “${endpoint}”`}. Both ends describe useful preferences. ${key==='map'?'Choose a point to open its story.':'Choose a bar to explore its meaning and a practical next step.'}`}
 return `<div class="graph-reading" data-no-translate><strong>${title}</strong><p>${text}</p></div>`;
}
export function allScenarioMarkup(scores,index,language='en'){const hi=language==='hi',story=lifeStory(scores,index,language),item=categoryInsight(scores,index);return `<div class="all-context-stories" data-no-translate>${Object.entries(hi?{daily:'रोज़मर्रा में',relationships:'रिश्तों में',pressure:'दबाव में'}:{daily:'Everyday life',relationships:'Relationships',pressure:'Under pressure'}).map(([key,label])=>`<div><h4>${label}</h4><p>${esc(story[key])}</p></div>`).join('')}<div><h4>${hi?'क्या मददगार हो सकता है':'What may help you feel supported'}</h4><p>${esc(story.need)}</p></div><div><h4>${hi?'आपकी खूबी':'Your strength'}</h4><p>${esc(item.strength)}</p></div><div><h4>${hi?'ध्यान रखने की बात':'One thing to watch for'}</h4><p>${esc(item.watch)}</p></div></div>`}
